/**
 * Threat Domain Entity
 *
 * Represents a detected security threat from AI manipulation attempts.
 */

export type ThreatSeverity = 'low' | 'medium' | 'high' | 'critical';

export type ThreatType =
  | 'prompt_injection'
  | 'jailbreak'
  | 'pii_exposure'
  | 'instruction_override'
  | 'role_switching'
  | 'context_manipulation'
  | 'encoding_attack'
  | 'unknown';

export interface Threat {
  readonly id: string;
  readonly type: ThreatType;
  readonly severity: ThreatSeverity;
  readonly confidence: number;
  readonly pattern: string;
  readonly description: string;
  readonly location?: {
    start: number;
    end: number;
  };
  readonly detectedAt: Date;
}

export interface ThreatDetectionResult {
  readonly safe: boolean;
  readonly threats: Threat[];
  readonly detectionTimeMs: number;
  readonly piiFound: boolean;
  readonly inputHash: string;
}

export interface BehavioralAnalysisResult {
  readonly agentId: string;
  readonly anomalyScore: number;
  readonly attractorType: 'point' | 'cycle' | 'torus' | 'strange';
  readonly lyapunovExponent: number;
  readonly analysisTimeMs: number;
  readonly windowSize: string;
  readonly actionCount: number;
}

export interface PolicyVerificationResult {
  readonly agentId: string;
  readonly policy: string;
  readonly valid: boolean;
  readonly violations: string[];
  readonly proofStatus: 'valid' | 'invalid' | 'timeout';
  readonly verificationTimeMs: number;
}

/**
 * Factory function to create a Threat entity
 */
export function createThreat(params: {
  type: ThreatType;
  severity: ThreatSeverity;
  confidence: number;
  pattern: string;
  description: string;
  location?: { start: number; end: number };
}): Threat {
  return {
    id: `threat-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
    type: params.type,
    severity: params.severity,
    confidence: params.confidence,
    pattern: params.pattern,
    description: params.description,
    location: params.location,
    detectedAt: new Date(),
  };
}

/**
 * Threat Detection Service
 *
 * Core detection logic for AI manipulation attempts.
 * Embedded implementation based on AIMDS patterns.
 *
 * Performance targets:
 * - Detection: <10ms
 * - Pattern matching: <5ms
 * - PII scan: <3ms
 */

import {
  Threat,
  ThreatType,
  ThreatSeverity,
  ThreatDetectionResult,
  createThreat
} from '../entities/threat.js';
import { createHash } from 'crypto';

/**
 * Threat pattern definition
 */
interface ThreatPattern {
  readonly pattern: RegExp;
  readonly type: ThreatType;
  readonly severity: ThreatSeverity;
  readonly description: string;
  readonly baseConfidence: number;
}

/**
 * Prompt injection patterns (50+ patterns from AIMDS)
 */
const PROMPT_INJECTION_PATTERNS: ThreatPattern[] = [
  // Instruction override patterns
  {
    pattern: /ignore\s+(all\s+)?(previous\s+)?instructions/i,
    type: 'instruction_override',
    severity: 'critical',
    description: 'Attempt to override system instructions',
    baseConfidence: 0.95,
  },
  {
    pattern: /forget\s+(everything|all|previous)/i,
    type: 'instruction_override',
    severity: 'critical',
    description: 'Attempt to reset system context',
    baseConfidence: 0.92,
  },
  {
    pattern: /disregard\s+(all\s+)?(previous|prior|above)/i,
    type: 'instruction_override',
    severity: 'critical',
    description: 'Attempt to disregard instructions',
    baseConfidence: 0.93,
  },
  {
    pattern: /do\s+not\s+follow\s+(the\s+)?(previous|above|prior)/i,
    type: 'instruction_override',
    severity: 'high',
    description: 'Attempt to bypass previous instructions',
    baseConfidence: 0.88,
  },

  // Role switching patterns
  {
    pattern: /you\s+are\s+now\s+(?!going|about|ready)/i,
    type: 'role_switching',
    severity: 'high',
    description: 'Attempt to change AI identity',
    baseConfidence: 0.85,
  },
  {
    pattern: /act\s+as\s+(if\s+you\s+are\s+)?a?\s*(different|new|another)/i,
    type: 'role_switching',
    severity: 'high',
    description: 'Attempt to assume different role',
    baseConfidence: 0.82,
  },
  {
    pattern: /pretend\s+(to\s+be|you\s+are)/i,
    type: 'role_switching',
    severity: 'medium',
    description: 'Roleplay instruction that may be legitimate',
    baseConfidence: 0.65,
  },

  // Jailbreak patterns
  {
    pattern: /\bDAN\b.*\bmode\b|\bmode\b.*\bDAN\b/i,
    type: 'jailbreak',
    severity: 'critical',
    description: 'DAN jailbreak attempt',
    baseConfidence: 0.98,
  },
  {
    pattern: /jailbreak/i,
    type: 'jailbreak',
    severity: 'critical',
    description: 'Explicit jailbreak mention',
    baseConfidence: 0.95,
  },
  {
    pattern: /bypass\s+(your\s+)?(restrictions|limitations|rules|filters)/i,
    type: 'jailbreak',
    severity: 'critical',
    description: 'Attempt to bypass restrictions',
    baseConfidence: 0.93,
  },
  {
    pattern: /without\s+(any\s+)?(restrictions|limitations|rules)/i,
