    type: 'credit_card',
    description: 'Credit card number',
  },
  {
    pattern: /\b(sk-[a-zA-Z0-9]{20,}|sk-ant-[a-zA-Z0-9-]{20,})\b/g,
    type: 'api_key',
    description: 'API key (OpenAI/Anthropic format)',
  },
  {
